CREATE VIEW std_ps4_inventory AS SELECT main."trim"(Title) AS game_title, Genre AS genre_raw, Theme AS theme_raw, "Mode" AS mode_raw, Perspective AS perspective_raw, "nullif"(main."trim"("Source"), 'N/A') AS acquisition_source_raw, "nullif"(main."trim"("File Location"), 'N/A') AS storage_location_raw, "nullif"(main."trim"(Status), 'N/A') AS play_status_raw, CASE  WHEN ((main."trim"(CAST("Owned?" AS VARCHAR)) = 'Y')) THEN (CAST('t' AS BOOLEAN)) WHEN ((main."trim"(CAST("Owned?" AS VARCHAR)) = 'N')) THEN (CAST('f' AS BOOLEAN)) ELSE NULL END AS owned_flag, TRY_CAST("nullif"("Difficulty (out of 5)", 'N/A') AS DECIMAL(3,2)) AS difficulty_rating, CASE  WHEN ((main."trim"("Game Length (in hours)") IN ('N/A', '???'))) THEN (NULL) ELSE TRY_CAST("Game Length (in hours)" AS DECIMAL(8,2)) END AS full_completion_hours, TRY_CAST("nullif"("File Size (in GB)", 'N/A') AS DECIMAL(10,2)) AS file_size_gb, 'PS4' AS platform_name FROM stg_ps4_inventory;
